"""Explicit modern subfamilies inside a Kuznetsova root family.

Each lemma is placed in one cluster. Clusters of the same dictionary
family do not share a game root. Lemmas listed as unresolved stay on the
dictionary family and match neither cluster.
"""

from __future__ import annotations

from collections import defaultdict
from pathlib import Path

from games.censorly.lexical.core import fold
from games.censorly.lexical.russian.compiler import (
    _families,
    _lines,
    _norm,
    _strip_note,
)


def install(sense, set_readings) -> None:
    for name, lemmas in CLUSTERS:
        sense(lemmas, name)
    for lemma, names in MULTI_READINGS:
        set_readings(lemma, names)


